CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "cff11fda-5f0d-450b-8113-6277664fb8e5",
  "snapshot_timestamp": "2026-05-21T19:45:07Z",
  "ticket_id": "6f7a-4ba6",
  "items": [
    {
      "original_text": "`ticket delete <id>` without `--user-approved` exits non-zero with an instructional error message directing the agent to confirm with the user and re-run with `--user-approved`; the `--user-approved` flag is absent from help text",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes durable system behavior where the command consistently requires explicit approval flagging and provides instructional errors"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "`ticket delete <id> --user-approved` exits non-zero with a clear error listing any child tickets not in `deleted` status",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior where the command consistently exhibits this error-handling property"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "`ticket delete <id> --user-approved` on a valid ticket atomically writes a `STATUS(deleted)` event and an `ARCHIVED` event in a single git commit",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (atomic deletion with dual events in git) that persists after implementation, phrased as ongoing capability"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "After deletion, `ticket list` (default output) excludes the deleted ticket; `ticket show <id>` still works and shows `status: deleted` and `archived: true`",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes durable system behavior for how deleted tickets are handled in list and show operations"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "`ticket transition <id> <current> deleted` exits non-zero with an error directing the user to `ticket delete`",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where a specific command produces an error with helpful guidance, not a one-time migration task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "On the next outbound bridge run, the bridge calls the Jira DELETE API for the ticket's Jira key; all subsequent sync operations for that ticket are skipped (idempotent); if Jira returns 403 (permission denied) the bridge writes a BRIDGE_ALERT and does not retry",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior for how the bridge handles ticket deletion and subsequent syncs, not a one-time migration or completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "All `depends_on` links where the deleted ticket is the blocking target (`target_id`) are removed via UNLINK events written atomically in the same git commit as the delete events",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time cleanup task that occurs during ticket deletion, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "`ticket transition <parent-id> <current> closed` does not fail due to child tickets in `deleted` status (`deleted` is added to `CLOSED_STATUSES` in the open-children guard)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where the ticket transition mechanism properly handles deleted child tickets without failing"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "An acceptance test confirms the end-to-end deletion workflow: `ticket delete --user-approved` on a test ticket followed by `ticket list` (excludes it), `ticket graph` (no edges to the deleted ID), and the outbound bridge mock/stub confirms the Jira DELETE API is called with the correct issue key",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time verification task (acceptance test confirmation) rather than an ongoing system property that persists after completion"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    }
  ]
}
